const FILES = [{"name":"agent-architecture-audit","size":4550,"b64":""},{"name":"agent-phase-ratchet","size":4003,"b64":""},{"name":"benchmark-optimization-loop","size":1415,"b64":""},{"name":"benchmark","size":1323,"b64":""},{"name":"browser-qa","size":2080,"b64":""},{"name":"codebase-onboarding","size":3662,"b64":""},{"name":"coding-judgment","size":2064,"b64":""},{"name":"conformance-gate","size":1257,"b64":""},{"name":"deep-research","size":2934,"b64":""},{"name":"dynamic-workflow-backlog","size":4017,"b64":""},{"name":"e2e-testing","size":3081,"b64":""},{"name":"ecc-advisor","size":2636,"b64":""},{"name":"ecc-guide","size":2538,"b64":""},{"name":"ecc-prompt-optimize","size":845,"b64":""},{"name":"ecc-role-catalog","size":646,"b64":""},{"name":"fuzz-regression","size":1211,"b64":""},{"name":"prompt-optimizer","size":7111,"b64":""},{"name":"token-budget-advisor","size":2705,"b64":""},{"name":"workflow-audit-router","size":2037,"b64":""}];

const grid = document.getElementById("grid");
const count = document.getElementById("count");

count.textContent = `${FILES.length} skills packaged \u2022 ${49} KB total \u2022 each imports as one skill`;

for (const file of FILES) {
  const a = document.createElement("a");
  a.className = "card";
  a.href = `data:application/zip;base64,${file.b64}`;
  a.download = `${file.name}.zip`;

  const name = document.createElement("span");
  name.className = "name";
  name.textContent = file.name;

  const meta = document.createElement("span");
  meta.className = "meta";
  meta.textContent = `${(file.size / 1024).toFixed(1)} KB \u2022 contains SKILL.md`;

  const dl = document.createElement("span");
  dl.className = "download";
  dl.textContent = "Download";

  a.append(name, meta, dl);
  grid.appendChild(a);
}

document.getElementById("download-all").addEventListener("click", () => {
  for (const file of FILES) {
    const a = document.createElement("a");
    a.href = `data:application/zip;base64,${file.b64}`;
    a.download = `${file.name}.zip`;
    document.body.appendChild(a);
    a.click();
    a.remove();
  }
});
